/* ============================================================================
   BANQUE DE PORTRAITS

   Les six photos fournies, réunies en une seule planche 3 × 2 et intégrées
   directement au code : aucune image à télécharger, tout fonctionne hors ligne
   et dans une page partagée.

   👉 POUR CHANGER LES PHOTOS : remplacer la planche ci-dessous par une autre
      image de six portraits disposés en trois colonnes et deux lignes.
      Le découpage se fait tout seul.

   La photo d'une personne se choisit dans src/data/contacts.ts, champ `photo`
   (0 à 5, de gauche à droite puis de haut en bas).
============================================================================ */

export const PORTRAIT_COLUMNS = 3
export const PORTRAIT_ROWS = 2
export const PORTRAIT_COUNT = PORTRAIT_COLUMNS * PORTRAIT_ROWS

/** Position de la planche pour afficher le portrait demandé. */
export function portraitPosition(index: number): { backgroundPosition: string; backgroundSize: string } {
  const safe = ((index % PORTRAIT_COUNT) + PORTRAIT_COUNT) % PORTRAIT_COUNT
  const column = safe % PORTRAIT_COLUMNS
  const row = Math.floor(safe / PORTRAIT_COLUMNS)

  return {
    backgroundSize: `${PORTRAIT_COLUMNS * 100}% ${PORTRAIT_ROWS * 100}%`,
    backgroundPosition: `${(column / (PORTRAIT_COLUMNS - 1)) * 100}% ${(row / (PORTRAIT_ROWS - 1)) * 100}%`,
  }
}

/** Choix stable d'un portrait pour un nom sans photo attribuée. */
export function portraitForName(name: string): number {
  let value = 0
  for (let index = 0; index < name.length; index++) {
    value = (value * 31 + name.charCodeAt(index)) % 100003
  }
  return value % PORTRAIT_COUNT
}

export const PORTRAIT_SHEET =
  "data:image/jpeg;base64,"
